regression.test.mjs:
import test from 'node:test';
import assert from 'node:assert/strict';
import {solve} from './logic.mjs';
test('contract boundaries',()=>{for(const [value,expected] of [[{"events": [{"kind": "end", "id": "x", "time": 1}]}, []], [{"events": [{"kind": "start", "id": "x", "time": 0}, {"kind": "start", "id": "x", "time": 3}, {"kind": "end", "id": "x", "time": 7}, {"kind": "end", "id": "x", "time": 9}]}, [{"id": "x", "elapsed": 4}]], [{"events": [{"kind": "start", "id": "__proto__", "time": 0}, {"kind": "end", "id": "__proto__", "time": 4}]}, [{"id": "__proto__", "elapsed": 4}]], [{"events": [{"kind": "start", "id": "x", "time": 4}, {"kind": "end", "id": "x", "time": 2}, {"kind": "end", "id": "x", "time": 9}]}, []]])assert.deepEqual(solve(value),expected);});
